-- 目标仓库: star-rain-v2/backend/star-rain-boot/src/main/resources/db/migration/V2_035__english_knowledge_taxonomy.sql
-- 生成基线 commit 93e6e3d；当前 V2 最后已知迁移 V2_034，执行前必须重新 git pull + 检查迁移版本。
-- 注意：本文件仅为实施模板，需要与本地最终 Flyway 配置、数据检查一致，严禁直接用于生产。
CREATE TABLE sr_english_taxonomy_term (
  id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  parent_id BIGINT NULL,
  dimension VARCHAR(20) NOT NULL COMMENT 'TOPIC/GENRE/PURPOSE',
  name VARCHAR(100) NOT NULL,
  name_en VARCHAR(150) NOT NULL,
  slug VARCHAR(200) NOT NULL,
  description VARCHAR(500) NULL,
  sort_order INT NOT NULL DEFAULT 10,
  enabled TINYINT(1) NOT NULL DEFAULT 1,
  is_world_baseline TINYINT(1) NOT NULL DEFAULT 0,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  UNIQUE KEY uk_sr_english_taxonomy_slug(slug),
  KEY idx_sr_english_taxonomy_tree(dimension,parent_id,sort_order,id),
  KEY idx_sr_english_taxonomy_baseline(dimension,is_world_baseline,parent_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
-- V2 逻辑外键：parent_id 由业务层校验存在、同 dimension、深度不超过两层、防环。


-- 以下查询为迁移后验收（Flyway 可在测试服务脚本调用）
SELECT dimension,COUNT(*) AS n FROM sr_english_taxonomy_term WHERE parent_id IS NULL GROUP BY dimension;
SELECT COUNT(*) AS topic_second_level FROM sr_english_taxonomy_term WHERE dimension='TOPIC' AND parent_id IS NOT NULL AND is_world_baseline=1;
